import os,sys,json,re,subprocess,shutil,stat
from pathlib import Path
from datetime import datetime,timezone
base=Path('/srv/projects')
names=['Codex','VPS','fadego','iptvpn-bot','lowcost-europa','pink-iptv','skill-universal','telegram-robot-leads']
services=['ssh','nginx','postgresql@16-main','pink-iptv-backend','pink-vpn','fadego-staging','lowcost-europa','pm2-iptvpn-bot','pm2-telegram-robot-leads']
def cmd(args,timeout=14,cwd=None):
 try:
  p=subprocess.run(args,capture_output=True,text=True,cwd=cwd,timeout=timeout,env={**os.environ,'GIT_OPTIONAL_LOCKS':'0','GIT_TERMINAL_PROMPT':'0'})
  return p.returncode,p.stdout.strip()
 except (OSError,subprocess.TimeoutExpired) as e:return 98,''
def g(repo,*args,t=12):
 return cmd(['git','-c','safe.directory='+str(repo),'-C',str(repo),*args],timeout=t)
rootdirs=[]
if base.is_dir():
 for p in base.iterdir():
  try:
   rootdirs.append({'name':p.name,'symlink':p.is_symlink(),'dir':p.is_dir(),'uid':p.lstat().st_uid})
  except OSError:continue
projects={}
for name in names:
 p=base/name
 d={'exists':p.is_dir(),'physical':p.is_dir() and not p.is_symlink()}
 if not d['physical']:
  projects[name]=d;continue
 d['uid']=p.stat().st_uid
 for child in ('.git','.venv','venv','node_modules','.runtime','current','releases','.staging','backup','backups','.env','dist','build','logs','tmp','cache'):
  q=p/child
  if q.exists() or q.is_symlink():
   d[child]={'link':q.is_symlink(),'dir':q.is_dir(),'file':q.is_file()}
   if q.is_symlink():
    try:d[child]['target_inside_project']=q.resolve(strict=True).is_relative_to(p.resolve(strict=True))
    except OSError:d[child]['target_inside_project']=False
 code,head=g(p,'rev-parse','HEAD');d['git_head']=head if code==0 else None
 code,branch=g(p,'branch','--show-current');d['git_branch']=branch if code==0 else None
 code,origin=g(p,'remote','get-url','origin')
 mt=re.search(r'(?:github\.com[:/])([^/:]+/[^/.]+)(?:\.git)?$',origin)
 d['remote_repo']=mt.group(1) if code==0 and mt else ('remote_exists_unparsed' if code==0 else None)
 code,tracking=g(p,'rev-parse','refs/remotes/origin/main')
 d['last_fetched_main']=tracking if code==0 else None
 code,status=g(p,'status','--porcelain','--untracked-files=no',t=22)
 d['tracked_change_count']=len(status.splitlines()) if code==0 else None
 code,pre=g(p,'stash','list',t=12)
 d['stash_count']=len(pre.splitlines()) if code==0 else None
 if name=='skill-universal':
  for link in (Path('/home/ubuntu/.local/share/motor-ferrari'),Path('/root/.local/share/motor-ferrari')):
   d['alias_'+('ubuntu' if 'ubuntu' in str(link) else 'root')]=link.exists() or link.is_symlink()
  for launcher in (p/'tools/apktool-3.0.3/bin/apktool',p/'tools/ferrari-services/valkey-server/bin/valkey-server'):
   if launcher.is_file() and not launcher.is_symlink():
    d['launcher_'+launcher.name+'_references_old_alias']=b'.local/share/motor-ferrari' in launcher.read_bytes()
  r=p/'.staging';d['staging_children']=[x.name[:70] for x in r.iterdir()][:20] if r.is_dir() else []
  d['active_release']=str((p/'current').resolve(strict=True)) if (p/'current').exists() else None
 projects[name]=d
svcs={}
for name in services:
 c,t=cmd(['systemctl','is-active',name],timeout=7)
 svcs[name]=t
check_links={}
for label,p in {'ferrari-home':Path('/home/ubuntu/.local/share/motor-ferrari'),'telegram-opt':Path('/opt/telegram-robot-leads'),'hopper-opt':Path('/opt/hopper'),'android-opt':Path('/opt/android-sdk'),'codex-home':Path('/home/ubuntu/codex-agent'),'codex-bridge-home':Path('/home/ubuntu/codex-bridge'),'root-android':Path('/root/.android'),'root-gradle':Path('/root/.gradle')}.items():
 if p.is_symlink():
  try:dest=str(p.resolve(strict=True));ok=True
  except OSError:dest='broken_link';ok=False
  check_links[label]={'type':'symlink','dest':dest[:180],'valid':ok}
 elif p.exists():check_links[label]={'type':'physical','is_dir':p.is_dir()}
 else:check_links[label]={'type':'absent'}
major=[]
for p in (Path('/srv'),Path('/opt'),Path('/var/tmp'),Path('/tmp'),Path('/home/ubuntu')):
 if not p.is_dir():continue
 try:
  child=sorted(p.iterdir(),key=lambda x:x.name)
  major.append({'dir':str(p),'entries_count':len(child),'names':[x.name for x in child[:100]] if p.name not in ('tmp','ubuntu') else [x.name for x in child[:70]]})
 except OSError:continue
for label,p in {'system_data':Path('/srv'),'root_fs':Path('/')}.items():
 d=shutil.disk_usage(p)
 major.append({'mount':label,'free_gb':round(d.free/1024**3,2),'total_gb':round(d.total/1024**3,2)})
out={'at':datetime.now(timezone.utc).isoformat(),'mode':'READ_ONLY','rootdirs':rootdirs,'projects':projects,'services':svcs,'legacy_paths':check_links,'top_level':major}
print(json.dumps(out,ensure_ascii=False,sort_keys=True))
